import pytest


def test_pairs_and_bare_keys():
    assert parse_logfmt("level=info msg=started debug") == {"level": "info", "msg": "started", "debug": True}
    assert parse_logfmt("   a=x    b=y   ") == {"a": "x", "b": "y"}
    assert parse_logfmt("") == {}
    assert parse_logfmt("    ") == {}
    assert parse_logfmt("k= z") == {"k": "", "z": True}
    assert parse_logfmt("svc.name=api-gw http-code=OK") == {"svc.name": "api-gw", "http-code": "OK"}


def test_quoted_values_and_escapes():
    assert parse_logfmt(r'msg="hello world" path="C:\\tmp"') == {"msg": "hello world", "path": "C:\\tmp"}
    assert parse_logfmt(r'q="say \"hi\"" e="" nl="a\nb"') == {"q": 'say "hi"', "e": "", "nl": "a\nb"}
    assert parse_logfmt(r'x="a=b c"') == {"x": "a=b c"}


def test_errors():
    for bad in ['a="x"b', 'a=b"c', 'a="abc', r'a="\t"', '=v', 'a==b', 'k@=1', 'a=1"', '"a"=1', 'a="x\\']:
        with pytest.raises(ValueError):
            parse_logfmt(bad)


def test_conversions():
    got = parse_logfmt('a=42 b=-7 c=007 d=true e=false f=True g="5" h="true" i=- j=4.5 k=+3 l=')
    assert got == {"a": 42, "b": -7, "c": 7, "d": True, "e": False, "f": "True", "g": "5",
                   "h": "true", "i": "-", "j": 4.5, "k": "+3", "l": ""}
    assert type(got["a"]) is int and type(got["d"]) is bool and type(got["g"]) is str
    assert type(got["j"]) is float


def test_float_conversion_edges():
    got = parse_logfmt('m=-0.25 n=1. o=.5 p=1.2.3 q=1e5 r="2.5" s=-.5 t=10.0')
    assert got == {"m": -0.25, "n": "1.", "o": ".5", "p": "1.2.3", "q": "1e5", "r": "2.5", "s": "-.5", "t": 10.0}
    assert type(got["t"]) is float and type(got["r"]) is str


def test_duplicate_keys_collect_lists():
    assert parse_logfmt("tag=a tag=b x=1 tag=3") == {"tag": ["a", "b", 3], "x": 1}
    got = parse_logfmt('f f=0 f="0" f=false')
    assert got == {"f": [True, 0, "0", False]}
    assert [type(v) for v in got["f"]] == [bool, int, str, bool]
    assert parse_logfmt("a=1 b=2") == {"a": 1, "b": 2}


def test_duplicate_keys_are_case_insensitive():
    assert parse_logfmt("Level=info level=warn LEVEL") == {"Level": ["info", "warn", True]}
    assert parse_logfmt("a=1 A=2.5 b=3") == {"a": [1, 2.5], "b": 3}
    assert parse_logfmt("Foo=1 bar=x") == {"Foo": 1, "bar": "x"}

import pytest


def test_sections_keys_and_comments():
    text = ("top = 1\n# comment\n   ; indented comment\n\n[Server]\nHost = example.com \n"
            "port=8080\n[ Paths ]\nroot = /var/www = x\n")
    assert parse_config(text) == {
        "": {"top": "1"},
        "Server": {"host": "example.com", "port": "8080"},
        "Paths": {"root": "/var/www = x"},
    }


def test_default_section_and_repeats():
    assert parse_config("[a]\n[b]\nx=1\n") == {"a": {}, "b": {"x": "1"}}
    assert parse_config("") == {}
    assert parse_config("# only a comment\n") == {}
    text = "[A]\nk = 1\n[a]\nk = 2\n[A]\nK = 3\nj =\n"
    assert parse_config(text) == {"A": {"k": "3", "j": ""}, "a": {"k": "2"}}


def test_errors():
    for bad in ["just text", "= value", "[a]\n  = 1", "[a]b", "[s]\n   orphan line\n"]:
        with pytest.raises(ValueError):
            parse_config(bad)


def test_continuation_lines():
    text = "[s]\nmsg = hello\n   big\n\tworld\nnext = 2\n"
    assert parse_config(text) == {"s": {"msg": "hello big world", "next": "2"}}


def test_continuation_takes_precedence_over_key_and_header_syntax():
    assert parse_config("a = 1\n  b = 2\n  [x]\n") == {"": {"a": "1 b = 2 [x]"}}


def test_comment_or_blank_line_ends_continuation():
    text = "a = 1\n  # note\n  b = 2\n\n  c = 3\n"
    assert parse_config(text) == {"": {"a": "1", "b": "2", "c": "3"}}
    assert parse_config("a = 1\n# note\n  b = 2\n;x\n\tc = 3\n") == {"": {"a": "1", "b": "2", "c": "3"}}


def test_references():
    text = ("[paths]\nroot = /srv\nlogs = ${root}/logs\n"
            "[app]\nlog = ${paths:LOGS}/app.log\nname = A$$B\n")
    assert parse_config(text) == {
        "paths": {"root": "/srv", "logs": "/srv/logs"},
        "app": {"log": "/srv/logs/app.log", "name": "A$B"},
    }


def test_references_use_final_values_and_are_not_rescanned():
    text = "[s]\na = ${b}!\nb = 1\nb = 2\nc = $${b}\nd = ${c}\n"
    assert parse_config(text) == {"s": {"a": "2!", "b": "2", "c": "${b}", "d": "${b}"}}


def test_reference_errors():
    for bad in ["[s]\na = ${nope}", "[s]\na = ${t:a}", "[s]\na = ${b}\nb = ${a}", "[s]\na = x${a}"]:
        with pytest.raises(ValueError):
            parse_config(bad)


def test_inline_comments():
    text = "a = 1 # c\nb = x;y\nurl = http://h/#frag\nk = #\n[s] ; sec\nz = 2\t;tab\nw = p # q = 3\n"
    assert parse_config(text) == {"": {"a": "1", "b": "x;y", "url": "http://h/#frag", "k": ""},
                                  "s": {"z": "2", "w": "p"}}


def test_inline_comment_on_continuation_line():
    assert parse_config("a = 1\n  more # note\n  end;x\n") == {"": {"a": "1 more end;x"}}

def test_overwrite_splits():
    assert paint([(0, 10, 'red'), (3, 5, 'blue')]) == [(0, 3, 'red'), (3, 5, 'blue'), (5, 10, 'red')]

def test_touching_same_color_merges_but_gap_does_not():
    assert paint([(0, 3, 'red'), (3, 6, 'red'), (7, 9, 'red')]) == [(0, 6, 'red'), (7, 9, 'red')]

def test_overwrite_can_create_merge():
    assert paint([(0, 4, 'red'), (4, 8, 'blue'), (4, 8, 'red')]) == [(0, 8, 'red')]

def test_empty_and_reversed_ranges():
    assert paint([(5, 5, 'red'), (9, 6, 'blue'), (1, 2, 'g')]) == [(1, 2, 'g'), (6, 9, 'blue')]
    assert paint([]) == []

def test_erase():
    assert paint([(0, 10, 'red'), (2, 4, None), (12, 8, None)]) == [(0, 2, 'red'), (4, 8, 'red')]

def test_erase_then_repaint_merges():
    assert paint([(0, 6, 'red'), (2, 4, None), (2, 4, 'red')]) == [(0, 6, 'red')]

def test_underpaint_only_fills_blank():
    assert paint([(2, 4, 'red'), (0, 10, '^blue')]) == [(0, 2, 'blue'), (2, 4, 'red'), (4, 10, 'blue')]

def test_underpaint_merges_with_neighbour():
    assert paint([(0, 3, 'red'), (5, 8, 'blue'), (8, 0, '^red')]) == [(0, 5, 'red'), (5, 8, 'blue')]

def test_underpaint_after_erase_then_overwrite():
    ops = [(0, 10, 'red'), (3, 6, None), (0, 10, '^green'), (5, 7, 'red')]
    assert paint(ops) == [(0, 3, 'red'), (3, 5, 'green'), (5, 10, 'red')]

def test_negative_coordinates():
    assert paint([(-5, -1, 'x'), (-1, -1, 'y'), (-3, -2, None)]) == [(-5, -3, 'x'), (-2, -1, 'x')]

def test_readiness_then_alphabetical():
    assert build_order({'a': ['z'], 'b': []}) == (['b', 'z', 'a'], [])
    assert build_order({'c': ['a'], 'b': ['a'], 'd': []}) == (['a', 'b', 'c', 'd'], [])

def test_implicit_tasks_and_duplicate_deps():
    deps = {'app': ['lib', 'lib', 'cfg'], 'lib': ['cfg']}
    assert build_order(deps) == (['cfg', 'lib', 'app'], [])

def test_priority_only_among_ready_tasks():
    deps = {'a': [], 'b': [], 'c': ['a']}
    assert build_order(deps, {'b': 2, 'c': 5}) == (['b', 'a', 'c'], [])

def test_missing_and_negative_priority():
    assert build_order({'x': [], 'y': [], 'z': []}, {'x': -1}) == (['y', 'z', 'x'], [])
    assert build_order({'b': [], 'a': []}, None) == (['a', 'b'], [])

def test_cycle_and_everything_downstream_is_stuck():
    deps = {'d': ['c'], 'c': ['a'], 'a': ['b'], 'b': ['c'], 'e': ['f'], 'g': []}
    assert build_order(deps) == (['f', 'e', 'g'], ['a', 'b', 'c', 'd'])

def test_self_dependency_is_a_cycle():
    assert build_order({'b': ['a'], 'a': ['a'], 'c': []}) == (['c'], ['a', 'b'])

def test_priority_with_cycle():
    deps = {'q': ['p'], 'p': ['q'], 's': ['r'], 'r': [], 't': ['s', 'q']}
    assert build_order(deps, {'s': 1, 'p': 9}) == (['r', 's'], ['p', 'q', 't'])

def test_priority_reorders_after_unlock():
    deps = {'m': ['k'], 'n': [], 'k': [], 'o': []}
    assert build_order(deps, {'m': 3, 'o': 1}) == (['o', 'k', 'm', 'n'], [])

def test_totals_and_ordering():
    r = [('ann', 10, 50), ('bob', 7, 20), ('ann', 2, 30), ('cat', 12, 90)]
    assert leaderboard(r) == [(1, 'ann', 12, 80), (2, 'cat', 12, 90), (3, 'bob', 7, 20)]

def test_competition_ranking_skips_after_ties():
    r = [('d', 5, 10), ('b', 5, 10), ('a', 9, 1), ('c', 1, 1), ('e', 5, 10)]
    assert leaderboard(r) == [(1, 'a', 9, 1), (2, 'b', 5, 10), (2, 'd', 5, 10), (2, 'e', 5, 10), (5, 'c', 1, 1)]

def test_equal_points_different_seconds_not_tied():
    assert leaderboard([('x', 3, 40), ('y', 3, 30)]) == [(1, 'y', 3, 30), (2, 'x', 3, 40)]

def test_disqualified_player_removed_entirely():
    r = [('ann', 10, 5), ('zed', 50, 1), ('bob', 8, 5), ('zed', -1, 0)]
    assert leaderboard(r) == [(1, 'ann', 10, 5), (2, 'bob', 8, 5)]

def test_penalty_first_and_zero_points_not_disqualified():
    r = [('q', -3, 0), ('q', 20, 1), ('p', 0, 0), ('r', 0, 0)]
    assert leaderboard(r) == [(1, 'p', 0, 0), (1, 'r', 0, 0)]

def test_disqualified_between_tied_groups():
    r = [('a', 9, 9), ('b', 9, 9), ('c', 8, 0), ('c', -2, 0), ('e', 7, 0), ('d', 7, 0), ('f', 1, 0)]
    assert leaderboard(r) == [(1, 'a', 9, 9), (1, 'b', 9, 9), (3, 'd', 7, 0), (3, 'e', 7, 0), (5, 'f', 1, 0)]

def test_empty():
    assert leaderboard([]) == []

def test_priority_and_idle_gap():
    jobs = [('a', 0, 3, 1), ('b', 1, 2, 5), ('c', 10, 1, 0)]
    assert run_jobs(jobs) == [('a', 0, 3), ('b', 3, 5), ('c', 10, 11)]

def test_arrival_exactly_when_free_is_eligible():
    jobs = [('a', 0, 4, 0), ('b', 0, 1, 0), ('z', 4, 1, 9)]
    assert run_jobs(jobs) == [('a', 0, 4), ('z', 4, 5), ('b', 5, 6)]

def test_tiebreak_arrival_then_name():
    jobs = [('m', 2, 1, 3), ('k', 1, 1, 3), ('j', 1, 1, 3), ('x', 0, 5, 0)]
    assert run_jobs(jobs) == [('x', 0, 5), ('j', 5, 6), ('k', 6, 7), ('m', 7, 8)]

def test_aging_lets_old_job_overtake():
    jobs = [('blocker', 0, 10, 9), ('old', 0, 1, 1), ('new', 9, 1, 2)]
    assert run_jobs(jobs) == [('blocker', 0, 10), ('old', 10, 11), ('new', 11, 12)]

def test_aging_counts_only_full_units():
    jobs = [('blocker', 0, 4, 9), ('old', 0, 1, 1), ('new', 4, 1, 2)]
    assert run_jobs(jobs) == [('blocker', 0, 4), ('new', 4, 5), ('old', 5, 6)]

def test_aging_tie_falls_back_to_arrival():
    jobs = [('blocker', 0, 9, 9), ('old', 0, 1, 1), ('new', 9, 1, 2)]
    assert run_jobs(jobs) == [('blocker', 0, 9), ('old', 9, 10), ('new', 10, 11)]

def test_aging_measured_from_arrival_across_several_picks():
    jobs = [('a', 0, 4, 9), ('b', 0, 4, 9), ('c', 0, 4, 9), ('w', 0, 1, 1), ('n', 12, 1, 2)]
    assert run_jobs(jobs) == [('a', 0, 4), ('b', 4, 8), ('c', 8, 12), ('w', 12, 13), ('n', 13, 14)]

def test_empty():
    assert run_jobs([]) == []

def test_half_open_window():
    ev = [(10, 1), (5, 2), (7, 4), (12, 8)]
    assert window_sums(ev, 5, 100) == [(5, 2), (7, 6), (10, 5), (12, 9)]

def test_shared_and_identical_events_all_count():
    ev = [(3, 1), (3, 1), (3, 5), (4, 2), (1, 10)]
    assert window_sums(ev, 3, 10) == [(1, 10), (3, 17), (4, 9)]

def test_gap_restarts_window():
    ev = [(0, 1), (2, 2), (7, 4), (8, 8)]
    assert window_sums(ev, 10, 4) == [(0, 1), (2, 3), (7, 4), (8, 12)]

def test_gap_equal_to_max_gap_does_not_restart():
    ev = [(0, 1), (4, 2), (8, 4)]
    assert window_sums(ev, 10, 4) == [(0, 1), (4, 3), (8, 7)]

def test_window_and_gap_together():
    ev = [(23, 64), (0, 1), (3, 2), (5, 4), (9, 8), (20, 16), (21, 32), (21, -2)]
    assert window_sums(ev, 4, 4) == [(0, 1), (3, 3), (5, 6), (9, 8), (20, 16), (21, 46), (23, 110)]

def test_empty():
    assert window_sums([], 5, 5) == []

import pytest

def test_best_fit_not_first_fit():
    assert pack([('a', 4), ('b', 1), ('c', 4), ('d', 7)], 10) == [['d'], ['a', 'c', 'b']]
    assert pack([('a', 8), ('b', 1), ('c', 4), ('d', 5), ('e', 1)], 10) == [['a', 'e'], ['d', 'c', 'b']]

def test_equal_sizes_alphabetical():
    assert pack([('q', 3), ('p', 3), ('r', 3)], 6) == [['p', 'q'], ['r']]

def test_best_fit_tie_goes_to_earliest_bin():
    assert pack([('y', 6), ('x', 6), ('z', 4)], 10) == [['x', 'z'], ['y']]

def test_exact_fill_and_oversize():
    assert pack([('a', 10), ('b', 10)], 10) == [['a'], ['b']]
    assert pack([], 5) == []
    with pytest.raises(ValueError):
        pack([('a', 3), ('big', 11)], 10)

def test_group_forces_worse_bin():
    assert pack([('big', 7, 'k'), ('mid', 5), ('small', 3, 'k')], 10) == [['big'], ['mid', 'small']]

def test_ungrouped_items_share_freely():
    assert pack([('a', 3), ('b', 3), ('c', 3, 'x')], 10) == [['a', 'b', 'c']]

def test_groups_with_best_fit():
    items = [('a', 8, 'red'), ('b', 1, 'blue'), ('c', 4), ('d', 5, 'blue'), ('e', 1, 'red')]
    assert pack(items, 10) == [['a', 'b'], ['d', 'c', 'e']]
    assert pack([('a', 5, 'g'), ('b', 5, 'g'), ('c', 5), ('d', 5)], 10) == [['a', 'c'], ['b', 'd']]

def test_basic_overlap():
    assert overlay([(1, 5, 'a'), (3, 8, 'b')]) == [(1, 2, ('a',)), (3, 5, ('a', 'b')), (6, 8, ('b',))]

def test_inclusive_adjacent_ranges_merge():
    assert overlay([(1, 3, 'x'), (4, 6, 'x'), (8, 9, 'x')]) == [(1, 6, ('x',)), (8, 9, ('x',))]

def test_same_label_set_from_different_ranges_merges():
    assert overlay([(0, 4, 'a'), (2, 6, 'b'), (5, 9, 'a')]) == [(0, 1, ('a',)), (2, 6, ('a', 'b')), (7, 9, ('a',))]

def test_single_points_and_empty():
    assert overlay([(5, 5, 'p'), (5, 5, 'q'), (6, 6, 'p')]) == [(5, 5, ('p', 'q')), (6, 6, ('p',))]
    assert overlay([]) == []

def test_min_count_counts_ranges_not_labels():
    r = [(1, 5, 'a'), (3, 5, 'a'), (4, 9, 'b')]
    assert overlay(r, 2) == [(3, 3, ('a',)), (4, 5, ('a', 'b'))]
    assert overlay(r) == [(1, 3, ('a',)), (4, 5, ('a', 'b')), (6, 9, ('b',))]

def test_min_count_grouping_by_label_set():
    assert overlay([(0, 9, 'a'), (2, 4, 'a'), (5, 6, 'a')], 2) == [(2, 6, ('a',))]
    assert overlay([(0, 9, 'a'), (2, 3, 'a'), (5, 6, 'a')], 2) == [(2, 3, ('a',)), (5, 6, ('a',))]
    assert overlay([(1, 5, 'a'), (3, 5, 'a')], 1) == [(1, 5, ('a',))]

def test_case_insensitive_labels():
    r = [(1, 4, 'Red'), (3, 6, 'red'), (2, 3, 'Blue'), (5, 5, 'apple')]
    assert overlay(r) == [(1, 1, ('red',)), (2, 3, ('blue', 'red')), (4, 4, ('red',)),
                          (5, 5, ('apple', 'red')), (6, 6, ('red',))]

def test_lowercase_before_sorting():
    assert overlay([(1, 2, 'Zeta'), (2, 3, 'apple'), (3, 3, 'ZETA')]) == [(1, 1, ('zeta',)), (2, 3, ('apple', 'zeta'))]
    assert overlay([(0, 3, 'A'), (2, 5, 'a')], 2) == [(2, 3, ('a',))]

def test_basic_round_robin():
    assert round_robin([('A', 0, 5), ('B', 1, 3), ('C', 2, 1)], 2, 0) == {'A': 9, 'B': 8, 'C': 5}

def test_arrival_at_slice_end_goes_before_preempted():
    assert round_robin([('A', 0, 4), ('B', 2, 1)], 2, 0) == {'A': 5, 'B': 3}

def test_idle_until_next_arrival_and_same_time_order():
    assert round_robin([('A', 0, 1), ('B', 5, 2)], 4, 0) == {'A': 1, 'B': 7}
    assert round_robin([('Z', 0, 1), ('Y', 0, 1)], 1, 0) == {'Z': 1, 'Y': 2}

def test_switch_cost_including_first_slice():
    assert round_robin([('A', 0, 3), ('B', 0, 2)], 2, 1) == {'A': 8, 'B': 6}

def test_no_switch_when_same_process_continues():
    assert round_robin([('A', 0, 5)], 2, 3) == {'A': 8}

def test_switch_after_idle():
    assert round_robin([('A', 0, 2), ('B', 10, 2)], 5, 1) == {'A': 3, 'B': 13}

def test_arrival_during_switch():
    assert round_robin([('A', 0, 2), ('B', 0, 3), ('C', 1, 1)], 2, 2) == {'A': 4, 'B': 14, 'C': 11}

def test_switch_with_arrival_at_slice_end():
    assert round_robin([('P', 0, 3), ('Q', 3, 2), ('R', 4, 1)], 2, 1) == {'P': 8, 'Q': 6, 'R': 10}

def test_half_open_reuse_and_unplaced():
    m = [('a', 0, 10, 5), ('b', 5, 15, 5), ('c', 10, 20, 5), ('d', 12, 13, 5)]
    assert assign_rooms(m, [10, 10]) == {'a': 1, 'b': 2, 'c': 1, 'd': None}

def test_smallest_fitting_capacity():
    m = [('x', 0, 5, 8), ('y', 0, 5, 9), ('w', 0, 5, 4), ('z', 0, 5, 3)]
    assert assign_rooms(m, [50, 8, 12, 8]) == {'w': 2, 'x': 4, 'y': 3, 'z': 1}

def test_order_start_then_end_then_id():
    m = [('long', 0, 10, 1), ('short', 0, 3, 1), ('later', 3, 6, 1)]
    assert assign_rooms(m, [5]) == {'long': None, 'short': 1, 'later': 1}

def test_too_big_for_every_room():
    assert assign_rooms([('ok', 0, 1, 5), ('big', 0, 1, 7)], [4, 6]) == {'big': None, 'ok': 2}

def test_series_uses_largest_attendee_count():
    m = [('s', 0, 1, 3), ('t', 0, 2, 2), ('s', 2, 3, 15)]
    assert assign_rooms(m, [4, 20, 20]) == {'s': 2, 't': 1}

def test_series_needs_room_free_for_all_occurrences():
    m = [('a', 5, 8, 1), ('s', 0, 2, 1), ('s', 6, 7, 1), ('b', 0, 1, 1), ('c', 5, 8, 1)]
    assert assign_rooms(m, [10, 10]) == {'b': 1, 's': 2, 'a': 1, 'c': None}

def test_series_ordered_by_first_occurrence_not_input_position():
    m = [('e', 4, 6, 1), ('s', 0, 1, 1), ('s', 5, 6, 1)]
    assert assign_rooms(m, [10, 10]) == {'s': 1, 'e': 2}

def test_plain_streaks_with_duplicates():
    log = [('a', 3), ('a', 1), ('a', 2), ('a', 2), ('a', 7), ('b', 10)]
    assert longest_streaks(log, freezes=0) == {'a': (3, 1), 'b': (1, 10)}

def test_tie_reports_earliest():
    assert longest_streaks([('u', 5), ('u', 6), ('u', 1), ('u', 2)], freezes=0) == {'u': (2, 1)}

def test_single_freeze_default():
    assert longest_streaks([('a', 1), ('a', 2), ('a', 4), ('a', 5)]) == {'a': (4, 1)}
    assert longest_streaks([('a', 1), ('a', 2), ('a', 4), ('a', 6)]) == {'a': (3, 1)}
    assert longest_streaks([('a', 1), ('a', 2), ('a', 5)]) == {'a': (2, 1)}

def test_two_day_gap_breaks():
    assert longest_streaks([('a', d) for d in (1, 2, 5, 6, 7)]) == {'a': (3, 5)}

def test_window_must_slide_past_old_gap():
    assert longest_streaks([('a', d) for d in (1, 3, 4, 5, 7, 8, 9, 10)]) == {'a': (7, 3)}

def test_freezes_parameter():
    log = [('a', d) for d in (1, 2, 4, 5, 7, 8)]
    assert longest_streaks(log) == {'a': (4, 1)}
    assert longest_streaks(log, freezes=2) == {'a': (6, 1)}
    assert longest_streaks(log, freezes=0) == {'a': (2, 1)}

def test_multiple_users():
    log = [('x', 1), ('x', 1), ('x', 3), ('y', 2), ('y', 4), ('y', 6), ('y', 8)]
    assert longest_streaks(log) == {'x': (2, 1), 'y': (2, 2)}
    assert longest_streaks(log, freezes=3) == {'x': (2, 1), 'y': (4, 2)}
    assert longest_streaks([]) == {}

def test_ties_at_cutoff_are_kept():
    rows = [('g', 'a', 5), ('g', 'b', 9), ('g', 'c', 7), ('g', 'd', 7), ('g', 'e', 1)]
    assert top_per_group(rows, 2) == {'g': ['b', 'c', 'd']}
